import { test, expect, type Page } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, uniqueName } from './helpers';

// The e2e isolation harness pre-provisions one namespace + one context per
// spec file and binds the logged-in node to it as the group. A fresh member
// lands on the group's display-name gate before any content shows.
async function joinGroupIfNeeded(page: Page, name: string) {
  const gate = page.getByTestId('group-join-gate');
  try {
    await gate.waitFor({ state: 'visible', timeout: 15_000 });
  } catch {
    return;
  }
  await page.getByTestId('field-display_name').fill(name);
  await page.getByTestId('action-set_display_name').click();
  await gate.waitFor({ state: 'hidden', timeout: 10_000 });
}

test.describe(`anyone in the group: see a spending dashboard — total spent and each person's paid and owed share`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
    await createWorkspace(page);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`the dashboard always shows the group's total spend and each member's total paid and total owed`, async ({ page }) => {
    const name = uniqueName('dana');
    await joinGroupIfNeeded(page, name);

    const description = uniqueName('taxi');
    await page.getByTestId('field-description').fill(description);
    await page.getByTestId('field-amount').fill('15');
    await page.getByTestId('action-add_expense').click();

    // The expense list confirms the add landed before we move to the
    // dashboard tab (the same context, no cross-node wait needed).
    await expect(
      page.locator('[data-testid^="item-expense-"]').filter({ hasText: description }),
    ).toBeVisible({ timeout: 10_000 });

    await page.getByTestId('tab-dashboard').click();

    // Total group spend is always shown, formatted as currency, and reflects
    // the expense this test just added (not a hardcoded UI label — the
    // amount ties the assertion to data this test created).
    const totalText = await page.locator('.num').first().textContent();
    expect(totalText).toMatch(/₹[\d,]+/);
    const totalValue = Number((totalText ?? '').replace(/[^\d]/g, ''));
    expect(totalValue).toBeGreaterThanOrEqual(15);

    // Each member's total paid and total owed are shown on the Members tab.
    // As the sole participant on every expense they've authored so far,
    // this member's paid and owed totals must be identical.
    await page.getByTestId('tab-members').click();
    const memberRow = page.locator('[data-testid^="item-member-"]').filter({ hasText: name });
    await expect(memberRow).toBeVisible({ timeout: 10_000 });
    const statText = (await memberRow.locator('.stat').textContent()) ?? '';
    const paidMatch = statText.match(/paid (₹[\d,]+)/);
    const owesMatch = statText.match(/owes (₹[\d,]+)/);
    expect(paidMatch, `expected a "paid ₹X" figure in "${statText}"`).not.toBeNull();
    expect(owesMatch, `expected an "owes ₹X" figure in "${statText}"`).not.toBeNull();
    expect(paidMatch![1]).toBe(owesMatch![1]);
  });
});
